ALTER TABLE public.materials ADD COLUMN IF NOT EXISTS semester smallint NOT NULL DEFAULT 1;
ALTER TABLE public.materials ADD COLUMN IF NOT EXISTS element text;
ALTER TABLE public.materials DROP CONSTRAINT IF EXISTS materials_semester_check;
ALTER TABLE public.materials ADD CONSTRAINT materials_semester_check CHECK (semester IN (1,2));

ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  subject = EXCLUDED.subject,
  grade = EXCLUDED.grade,
  semester = EXCLUDED.semester,
  element = EXCLUDED.element,
  description = EXCLUDED.description,
  duration = EXCLUDED.duration,
  module_list = EXCLUDED.module_list,
  is_published = true;